<script>
export default {
    name: 'CursorIcon',
    mounted() {
        document.addEventListener('mousemove', this.updateCursorPosition)
    },
    beforeUnmount() {
        document.removeEventListener('mousemove', this.updateCursorPosition)
    },
    methods: {
        updateCursorPosition(e) {
            const cursor = document.querySelector('.cursor-container')
            if (cursor) {
                cursor.style.left = `${e.clientX}px`
                cursor.style.top = `${e.clientY}px`
            }
        },
    },
}
</script>

<style scoped>
.cursor-container {
    position: fixed;
    pointer-events: none;
    z-index: 9999;
    transform: translate(-5px, -24px); /* Điều chỉnh vị trí tương tự như cursor.scss */
    @apply text-[#B8CA34];
}

/* Áp dụng style khi hover vào các phần tử */
:deep(.btn:hover),
:deep(a:hover),
:deep(button:hover),
:deep(.cursor-pointer:hover),
:deep([role='button']:hover) {
    @apply text-red-fks;
}
</style>
